// BLO-29553 AC1(b): redact credential shapes BEFORE `tee` writes the pod log.
//
// `claude --output-format stream-json` is piped through `tee <podLogPath>` into
// the fail-fast awk filter (job-manifest.ts). `podLogPath` is a file on the
// SHARED CephFS PVC, and nothing on that leg redacted anything: the whole
// adapter package contained zero redaction calls. The server does redact — but
// only the *derived* copy it tails into `runLogStore` (heartbeat.ts:4067-4068
// `redactSensitiveText`), never the file itself. So a credential the model
// echoed landed on the PVC in the clear, in FULL, while the store got the
// redacted version. The file is normally unlinked by `cleanupJob`; it survives
// on the orphan path.
//
// Of the three candidate fixes, (ii) "drop the pod-side file" is void — that
// file IS the pod->server transport (`execute.ts:2338` tails it, `:2352` reads
// it back for the parse) — and (iii) "bound the orphan retention window" is
// owned and moving on BLO-32734 AC2. This is (i): redact at the `tee`, ruled by
// the CEO 2026-09-08, following the `failFastFilter` precedent of doing stream
// work in-pod rather than after the fact.
//
// This is defence in depth, NOT the durable boundary. BLO-21027 (remove the
// credential from the pod at all) is the boundary; nothing here may be relied on
// to decide who may read a pod log.

import { createHash } from "node:crypto";

/**
 * Line filter installed into the pod and spliced in front of `tee`.
 *
 * ## Why this is a second copy of the rules, and what stops it rotting
 *
 * The rules live in `@paperclipai/adapter-utils/command-redaction`, which the
 * SERVER imports directly. The pod cannot: the adapter package is not on the pod
 * image, the module is TypeScript, and the one in-pod runtime we are sure of is
 * whatever `node` the `claude` CLI ships against — so `--experimental-strip-types`
 * is not a safe assumption. Shipping the source and stripping its handful of type
 * annotations with a regex would fail silently the first time that file grows
 * syntax the stripper does not know.
 *
 * So this mirrors the repo's own established answer to exactly this problem,
 * twice over: `ENV_GUARD_SCRIPT` carries a second copy of
 * `classifyAgentShellCommand` and `env-guard.test.ts` runs one corpus through
 * both; `CREDENTIAL_VALUE_RES` and `command-redaction.ts`'s rules are held in
 * parity "by a test, not by convention". `pod-log-redactor.test.ts` does both
 * halves here — it asserts every regex literal in `command-redaction.ts` appears
 * in this script (structural, so a NEW rule cannot be silently forgotten), and
 * runs a shared corpus through both (behavioural, so a reordering is caught).
 *
 * ## Why the embedded script contains no backtick and no template literal
 *
 * It is carried in a `String.raw` template, so a literal backtick in the body
 * would terminate it and every regex here has `[^\s"'`]`-shaped classes. Writing
 * those as `\x60` keeps the body backtick-free and the escaping reviewable. The
 * parity test normalises the same way before comparing.
 *
 * ## Why it redacts JSON string VALUES rather than the raw line
 *
 * The stream is one JSON object per line and the server PARSES it (`execute.ts`
 * `stdout` -> result parser). Raw-text redaction can span a quote or a comma —
 * `COMMAND_PEM_PRIVATE_KEY_RE` is `[\s\S]*?` — and would hand the parser a
 * broken line, turning a redaction fix into a run-failure bug on an already
 * fragile path. Walking the parsed value and redacting each string cannot
 * produce invalid JSON, because the result is re-serialised. Non-JSON lines
 * (wrapper diagnostics, a line cut mid-write) fall back to raw redaction, which
 * is where byte parity with `redactCommandText` is asserted.
 *
 * ## Failure posture
 *
 * Fail OPEN per line, fail CLOSED never. A throw inside the redactor is our bug,
 * not an attacker's input, and the alternatives are both worse than emitting the
 * original line: dropping it corrupts the transport and the parse, and crashing
 * takes the run down via `set -o pipefail`. The shell fragment additionally
 * degrades to a plain `cat` when the script is not on disk, so a failed install
 * can never wedge the fleet.
 */
export const POD_LOG_REDACTOR_SCRIPT = String.raw`#!/usr/bin/env node
// paperclip-pod-log-redactor.mjs — BLO-29553. Generated by
// paperclip-adapter-claude-k8s; do not edit in the pod.
//
// Mirror of redactCommandText() in @paperclipai/adapter-utils/command-redaction.
// Parity — both the regex literals and the ORDER they run in — is enforced by
// pod-log-redactor.test.ts. Change one, change the other.
//
// No backticks and no template literals below: the whole file is carried inside
// a String.raw template on the server side. \x60 is a backtick.
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";

const REDACTED = "***REDACTED***";

const SECRET_NAME_PATTERN =
  "[A-Za-z0-9_-]*(?:api[-_]?key|(?:access[-_]?|auth[-_]?)?token|token|authorization|bearer|secret|passwd|password|credential|jwt|private[-_]?key|cookie|connectionstring)[A-Za-z0-9_-]*";

const COMMAND_CLI_SECRET_OPTION_RE = new RegExp(
  "(\\B-{1,2}" + SECRET_NAME_PATTERN + "(?:\\s+|=)([\"']?))[^\\s\"'\\x60]+(\\2)",
  "gi",
);
const COMMAND_ENV_SECRET_ASSIGNMENT_RE = new RegExp(
  "(\\b" + SECRET_NAME_PATTERN + "\\s*=\\s*)(?:([\"'])([^\"'\\x60\\r\\n]*)\\2|([^\\s\"'\\x60]+))",
  "gi",
);
const COMMAND_AUTHORIZATION_BEARER_RE = /(\bAuthorization\s*:\s*Bearer\s+)[^\s"'\x60]+/gi;
const COMMAND_OPENAI_KEY_RE = /\bsk-[A-Za-z0-9_-]{12,}\b/g;
const COMMAND_GITHUB_TOKEN_RE = /\bgh[pousr]_[A-Za-z0-9_]{20,}(?:\.[A-Za-z0-9_-]+)*\b/g;
const COMMAND_GITHUB_FINE_GRAINED_PAT_RE = /\bgithub_pat_[A-Za-z0-9_]{20,}(?:\.[A-Za-z0-9_-]+)*\b/g;
const COMMAND_AWS_ACCESS_KEY_ID_RE = /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g;
const COMMAND_GOOGLE_API_KEY_RE = /\bAIza[0-9A-Za-z_-]{20,}/g;
const COMMAND_SLACK_TOKEN_RE = /\bxox[baprs]-[A-Za-z0-9-]{10,}/g;
const COMMAND_PEM_PRIVATE_KEY_RE =
  /-----BEGIN (?:[A-Z0-9 ]+ )?PRIVATE KEY-----(?:[\s\S]*?-----END (?:[A-Z0-9 ]+ )?PRIVATE KEY-----|(?:(?:\s|\\[rn])+[A-Za-z0-9+/=]{16,})*(?:(?:\s|\\[rn])+[A-Za-z0-9+/=]{1,15}(?:\s|\\[rn])*$)?)/g;
const COMMAND_JWT_RE =
  /\b[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}(?:\.[A-Za-z0-9_-]{8,})*\b/g;

const COMMAND_SECRET_HINTS = [
  "api", "key", "token", "auth", "bearer", "secret", "pass", "credential",
  "jwt", "private", "cookie", "connectionstring", "sk-", "ghp_", "gho_",
  "ghu_", "ghs_", "ghr_", "akia", "asia", "aiza", "xox", "github_pat_",
];

function maybeContainsSecretText(text) {
  const lower = text.toLowerCase();
  return COMMAND_SECRET_HINTS.some(function (hint) { return lower.includes(hint); })
    || text.includes(".");
}

// ORDERING INVARIANT — see the long note on redactCommandText(). The three
// name-anchored rules consume their whole value and are order-free; the two
// GitHub rules must PRECEDE JWT (they are self-sufficient over a dotted tail,
// JWT is not), and COMMAND_OPENAI_KEY_RE must FOLLOW JWT (it is prefix-anchored
// and not self-sufficient, so ahead of JWT it would replace only a prefix and
// destroy the structure JWT matches on — the original 2-of-3-segments leak).
export function redactText(text) {
  if (!maybeContainsSecretText(text)) return text;
  return text
    .replace(COMMAND_AUTHORIZATION_BEARER_RE, "$1" + REDACTED)
    .replace(COMMAND_CLI_SECRET_OPTION_RE, "$1" + REDACTED + "$3")
    .replace(COMMAND_ENV_SECRET_ASSIGNMENT_RE, function (_match, prefix, quote) {
      return quote ? prefix + quote + REDACTED + quote : prefix + REDACTED;
    })
    .replace(COMMAND_GITHUB_FINE_GRAINED_PAT_RE, REDACTED)
    .replace(COMMAND_GITHUB_TOKEN_RE, REDACTED)
    .replace(COMMAND_AWS_ACCESS_KEY_ID_RE, REDACTED)
    .replace(COMMAND_GOOGLE_API_KEY_RE, REDACTED)
    .replace(COMMAND_SLACK_TOKEN_RE, REDACTED)
    .replace(COMMAND_PEM_PRIVATE_KEY_RE, REDACTED)
    .replace(COMMAND_JWT_RE, REDACTED)
    .replace(COMMAND_OPENAI_KEY_RE, REDACTED);
}

/** Redact every string reachable in a parsed JSON value. */
function redactJsonValue(value) {
  if (typeof value === "string") return redactText(value);
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) value[i] = redactJsonValue(value[i]);
    return value;
  }
  if (value && typeof value === "object") {
    for (const k of Object.keys(value)) value[k] = redactJsonValue(value[k]);
    return value;
  }
  return value;
}

export function redactLine(line) {
  if (line === "") return line;
  try {
    // Only re-serialise what parses as a JSON object/array. Anything else is
    // prose and takes the raw path, where byte parity with redactCommandText()
    // holds.
    const parsed = JSON.parse(line);
    if (parsed !== null && typeof parsed === "object") {
      return JSON.stringify(redactJsonValue(parsed));
    }
  } catch (_e) { /* not JSON — fall through to raw */ }
  return redactText(line);
}

// Fail OPEN per line: a throw here is our bug, and emitting the original beats
// dropping the line (corrupts the transport and the server-side parse) or dying
// (set -o pipefail would fail the whole run).
export function safeRedactLine(line) {
  try {
    return redactLine(line);
  } catch (_e) {
    return line;
  }
}

export function createRedactTransform() {
  let residue = "";
  return new Transform({
    decodeStrings: false,
    transform(chunk, _enc, cb) {
      residue += chunk;
      let out = "";
      let i = residue.indexOf("\n");
      while (i >= 0) {
        out += safeRedactLine(residue.slice(0, i)) + "\n";
        residue = residue.slice(i + 1);
        i = residue.indexOf("\n");
      }
      cb(null, out);
    },
    flush(cb) {
      cb(null, residue ? safeRedactLine(residue) : "");
    },
  });
}

if (process.argv[1] && import.meta.url === new URL("file://" + process.argv[1]).href) {
  process.stdin.setEncoding("utf8");
  // EPIPE is the NORMAL shutdown here: the fail-fast awk downstream exits 1 on a
  // terminal rate-limit event, which unwinds the pipe back through tee to us.
  // Exit 0 quietly and let awk's own non-zero code drive set -o pipefail.
  const onErr = function (e) { if (e && e.code === "EPIPE") process.exit(0); };
  process.stdout.on("error", onErr);
  process.stdin.on("error", onErr);
  pipeline(process.stdin, createRedactTransform(), process.stdout).catch(function (e) {
    if (e && e.code === "EPIPE") process.exit(0);
    process.exit(1);
  });
}
`;

/** Content-addressed so a rule change lands as a NEW file rather than an
 *  in-place rewrite of the one every pod in the fleet shares. Same reason as the
 *  env guard: `$GUARD_DIR` is RWX CephFS, and a wedged truncate there once
 *  blocked `open()` fleet-wide. */
export const POD_LOG_REDACTOR_FILENAME = `paperclip-pod-log-redactor.${createHash("sha256")
  .update(POD_LOG_REDACTOR_SCRIPT, "utf8")
  .digest("hex")
  .slice(0, 12)}.mjs`;

/** Shell variables the pipeline reads. Exported so job-manifest and its tests
 *  cannot drift on the spelling.
 *
 *  Deliberately TWO variables, command and argument, rather than one holding
 *  `node <path>`: the path is `$GUARD_DIR/<hex>.mjs` and `$GUARD_DIR` is
 *  `${CLAUDE_CONFIG_DIR:-$HOME/.claude}` (`env-guard.ts`), where
 *  `CLAUDE_CONFIG_DIR` is operator-configurable via adapter config
 *  (`resolveClaudeConfigDir()` in job-manifest.ts). A configured value
 *  containing whitespace word-splits a single unquoted `$VAR` into
 *  `node /a` + `b/...mjs`, which exits non-zero and takes every run on that
 *  config down through `set -o pipefail`. The `[ -f ]` fail-open does NOT
 *  catch that — its own test is quoted and passes, so the broken command is
 *  what gets installed. Splitting the two lets the pipeline quote both. */
export const POD_LOG_FILTER_VAR = "PAPERCLIP_POD_LOG_FILTER";
export const POD_LOG_FILTER_ARG_VAR = "PAPERCLIP_POD_LOG_FILTER_ARG";

/**
 * `;`-joinable fragment that installs the redactor and sets
 * `$PAPERCLIP_POD_LOG_FILTER` (+ `_ARG`) to the command that goes in front of
 * `tee`.
 *
 * Runs AFTER `buildEnvGuardSetupShell()`, which already created `$GUARD_DIR`.
 * It does NOT establish that `node` is runnable — its one node use is
 * `... | node - 2>/dev/null || echo ... >&2`, explicitly fail-soft — so this
 * fragment probes `command -v node` itself rather than assuming.
 *
 * The fallback to `cat` is the fail-open: if the install lost a race, the
 * volume is unwritable, or node is missing, the pipeline degrades to today's
 * behaviour instead of `set -o pipefail` failing every run in the fleet.
 */
export function buildPodLogRedactorSetupShell(): string {
  const b64 = Buffer.from(POD_LOG_REDACTOR_SCRIPT, "utf8").toString("base64");
  const target = `$GUARD_DIR/${POD_LOG_REDACTOR_FILENAME}`;
  const tmp = `$GUARD_DIR/.${POD_LOG_REDACTOR_FILENAME}.$$.tmp`;
  return [
    `[ -f "${target}" ] || { printf %s '${b64}' | base64 -d > "${tmp}" && mv -f "${tmp}" "${target}"; }`,
    `${POD_LOG_FILTER_VAR}=cat`,
    `${POD_LOG_FILTER_ARG_VAR}=`,
    `command -v node >/dev/null 2>&1 && [ -f "${target}" ] && { ${POD_LOG_FILTER_VAR}=node; ${POD_LOG_FILTER_ARG_VAR}="${target}"; }`,
    `export ${POD_LOG_FILTER_VAR} ${POD_LOG_FILTER_ARG_VAR}`,
  ].join("; ");
}
